/**
 * Model-facing failure contract and fixed recovery policy.
 *
 * Only the declared codes, fixed messages and bounded allowlisted metadata may
 * leave the app. Request IDs are generated by the application, not copied from an
 * upstream body. `INVALID_INPUT` may carry at most eight field/reason details
 * derived from schema keys, or the caller's own unrecognized key names; values,
 * raw schema messages, upstream text and signed links never cross this boundary.
 * The `toolError` function emits isError plus equivalent JSON text/structured
 * error.
 * TOKEN_REFRESH_FAILED is retryable only for proven transient_refresh evidence;
 * unknown grant consumption is non-retryable. HTTP/protocol failure domains remain
 * separate from application tool failures. Do not infer lifecycle evidence from
 * exception messages or include token documents, headers or signed cache URLs.
 */
import { randomUUID } from "node:crypto";
import { z } from "zod";

/** Fixed recovery text is the only source of outward-facing messages. */
export const errorPolicy = Object.freeze({
  INVALID_INPUT: ["Correct the tool input and try again.", false],
  AUTHORIZATION_REQUIRED: [
    "Authorization is required. Ask the host to restore access.",
    false,
  ],
  TOKEN_REFRESH_FAILED: [
    "Token refresh failed. Retry only when marked retryable; otherwise ask the host to restore access.",
    false,
  ],
  UPSTREAM_UNAUTHORIZED: [
    "iRacing rejected access (401/403). Check the selected credentials, token validity, scopes, and account permissions.",
    false,
  ],
  RATE_LIMITED: [
    "Request capacity is temporarily limited. Wait before retrying.",
    true,
  ],
  UPSTREAM_UNAVAILABLE: [
    "iRacing is temporarily unavailable. Try again later.",
    true,
  ],
  DATA_RESOLUTION_FAILED: [
    "Data could not be safely resolved. Give the request ID to support.",
    false,
  ],
  RESPONSE_LIMIT_EXCEEDED: [
    "Narrow the request. The source or response exceeds the app limit.",
    false,
  ],
  NOT_FOUND: [
    "No matching data was found. Check the requested identifiers.",
    false,
  ],
  CONFIGURATION_ERROR: [
    "The host configuration needs repair. Contact the host operator.",
    false,
  ],
  INTERNAL_ERROR: [
    "An unexpected failure occurred. Give the request ID to support.",
    false,
  ],
} as const);

for (const policy of Object.values(errorPolicy)) {
  Object.freeze(policy);
}

/**
 * Stable application failure codes that may cross the MCP diagnostic boundary without exposing
 * implementation details.
 */
export type ApplicationErrorCode = keyof typeof errorPolicy;
const codes = Object.keys(errorPolicy) as [
  ApplicationErrorCode,
  ...ApplicationErrorCode[],
];

/** Restricts application failures to the maintained secret-safe error-code set. */
export const ApplicationErrorCodeSchema = z.enum(codes);
const reasons = {
  AUTHORIZATION_REQUIRED: [
    "missing_session",
    "revoked_authorization",
    "invalid_session",
    "insufficient_scope",
    "rotation_uncertain",
    "persistence_failed",
  ],
  TOKEN_REFRESH_FAILED: ["transient_refresh", "rotation_uncertain"],
  UPSTREAM_UNAUTHORIZED: ["account_entitlement", "upstream_access_denied"],
  DATA_RESOLUTION_FAILED: [
    "invalid_data",
    "unsafe_link",
    "link_expired",
    "link_rejected",
  ],
} as const;

/**
 * Machine-readable reasons for rejected tool input.
 *
 * Reasons describe the field only; rejected values, upstream text and raw schema
 * messages never cross the boundary. `unknown_field` names a key the caller
 * supplied that the input schema does not declare, so its field is caller-owned
 * text bounded by {@link ErrorDetailSchema}, never a schema key.
 */
export const DetailReasonSchema = z.enum([
  "unsupported_for_source",
  "required_for_source",
  "required_together",
  "missing_range",
  "range_end_before_begin",
  "range_too_wide",
  "begin_in_future",
  "unknown_field",
  "invalid_value",
  "invalid_format",
]);
export type DetailReason = z.infer<typeof DetailReasonSchema>;

/** One bounded field-level input diagnostic. */
export const ErrorDetailSchema = z.strictObject({
  field: z
    .string()
    .max(64)
    .regex(/^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*$/),
  reason: DetailReasonSchema,
});
export type ErrorDetail = z.infer<typeof ErrorDetailSchema>;

/** Upper bound on retained field diagnostics for one error envelope. */
export const maximumErrorDetails = 8;

/**
 * Expected operation failure with code-specific, secret-safe reason metadata.
 * Retry delays require a retryable policy or explicit transient-refresh evidence.
 * Field details are accepted only for `INVALID_INPUT`.
 * Runtime serialization still passes through ApplicationFailure's allowlist.
 */
export type FailureFor<
  Code extends ApplicationErrorCode = ApplicationErrorCode,
> = {
  [Key in Code]: {
    readonly code: Key;
  } & (Key extends "INVALID_INPUT"
    ? { readonly details?: readonly ErrorDetail[] }
    : { readonly details?: never }) &
    (Key extends "TOKEN_REFRESH_FAILED"
      ? | {
            readonly reason: "transient_refresh";
            readonly retry_after_seconds?: number;
          }
        | {
            readonly reason?: Exclude<
              (typeof reasons)["TOKEN_REFRESH_FAILED"][number],
              "transient_refresh"
            >;
            readonly retry_after_seconds?: never;
          }
      : {
          readonly retry_after_seconds?: (typeof errorPolicy)[Key][1] extends true
            ? number
            : never;
        } & (Key extends keyof typeof reasons
          ? { readonly reason?: (typeof reasons)[Key][number] }
          : { readonly reason?: never }));
}[Code];

/** Validates bounded, secret-safe tool errors and their correlation identifiers. */
export const ErrorEnvelopeSchema = z
  .strictObject({
    error: z.strictObject({
      code: ApplicationErrorCodeSchema,
      message: z.string().max(180),
      retryable: z.boolean(),
      request_id: z.uuid(),
      reason: z.string().max(40).optional(),
      retry_after_seconds: z.int().min(0).max(3600).optional(),
      details: z.array(ErrorDetailSchema).max(maximumErrorDetails).optional(),
    }),
  })
  .superRefine(({ error }, ctx) => {
    const allowed = reasons[error.code as keyof typeof reasons] as
      readonly string[] | undefined;

    if (error.reason !== undefined && !allowed?.includes(error.reason)) {
      ctx.addIssue({ code: "custom", message: "Invalid error reason" });
    }

    if (error.details !== undefined) {
      refineDetails(error, ctx);
    }

    const safeRefresh =
      error.code === "TOKEN_REFRESH_FAILED" &&
      error.reason === "transient_refresh";

    if (
      error.message !== errorPolicy[error.code][0] ||
      error.retryable !== (safeRefresh || errorPolicy[error.code][1])
    ) {
      ctx.addIssue({ code: "custom", message: "Invalid error policy" });
    }

    if (error.retry_after_seconds !== undefined && !error.retryable) {
      ctx.addIssue({ code: "custom", message: "Invalid retry metadata" });
    }
  });

/** Field details are an `INVALID_INPUT` affordance and stay bounded and ordered. */
function refineDetails(
  error: { code: ApplicationErrorCode; details?: ErrorDetail[] },
  ctx: z.RefinementCtx,
): void {
  if (error.code !== "INVALID_INPUT") {
    ctx.addIssue({ code: "custom", message: "Input details require input" });
  }

  if (!isOrdered(error.details ?? [])) {
    ctx.addIssue({ code: "custom", message: "Unordered input details" });
  }
}

export type ErrorEnvelope = z.infer<typeof ErrorEnvelopeSchema>;

// Contexts are generated here, never accepted from a client or upstream ID.
const contexts = new WeakMap<RequestContext, string>();

/**
 * Opaque request-correlation handle whose identifier is owned internally rather than trusted
 * from arbitrary object properties.
 */
export interface RequestContext {
  /** Opaque correlation identifier safe to include in tool errors. */
  readonly request_id: string;
}

/**
 * Creates a fresh immutable correlation context backed by an internally owned request
 * identifier.
 * @returns {RequestContext} Fresh opaque request-correlation context.
 */
export function createRequestContext(): RequestContext {
  const context = Object.freeze({ request_id: randomUUID() });

  contexts.set(context, context.request_id);

  return context;
}

/**
 * Returns the owned identifier for a known request context and refuses to trust
 * caller-supplied lookalike properties.
 * @param {RequestContext} context - Request-local identity, cancellation, or diagnostic context.
 * @returns {string} Safe correlation identifier for the request.
 */
export function requestId(context: RequestContext): string {
  return contexts.get(context) ?? createRequestContext().request_id;
}

const failures = new WeakMap<
  ApplicationFailure,
  Readonly<{
    code: ApplicationErrorCode;
    reason?: string;
    retry_after_seconds?: number;
    details?: readonly ErrorDetail[];
  }>
>();

/**
 * Canonical application-level failure exposed through the MCP tool error contract.
 *
 * Instances carry only an allowlisted {@link ApplicationErrorCode} plus bounded metadata.
 * Callers cannot supply an outward-facing message, nested cause, stack payload, or arbitrary
 * diagnostics; serialization always derives recovery text from {@link errorPolicy}.
 */
export class ApplicationFailure extends Error {
  /**
   * Creates a sanitized application failure.
   *
   * @param {ApplicationErrorCode} code Stable application error code. Invalid values degrade to `INTERNAL_ERROR`.
   * @param {unknown} options Optional allowlisted `reason` and retry delay metadata.
   */
  constructor(code: ApplicationErrorCode, options: unknown = {}) {
    const validCode = ApplicationErrorCodeSchema.safeParse(code);

    const safeCode = validCode.success ? validCode.data : "INTERNAL_ERROR";

    super(errorPolicy[safeCode][0]);
    this.name = "ApplicationFailure";
    const parsed = z
      .object({
        reason: z.string().optional(),
        retry_after_seconds: z.number().optional(),
        details: z.unknown().optional(),
      })
      .safeParse(options);

    const input = parsed.success ? parsed.data : {};

    const allowed = reasons[safeCode as keyof typeof reasons] as
      readonly string[] | undefined;

    const reason = allowed?.includes(input.reason ?? "")
      ? input.reason
      : undefined;

    const retryable =
      errorPolicy[safeCode][1] ||
      (safeCode === "TOKEN_REFRESH_FAILED" && reason === "transient_refresh");

    const seconds = input.retry_after_seconds;

    const details =
      safeCode === "INVALID_INPUT"
        ? normalizeDetails(input.details)
        : undefined;

    failures.set(
      this,
      Object.freeze({
        code: safeCode,
        ...(reason ? { reason } : {}),
        ...retryMetadata(retryable, seconds),
        ...(details ? { details } : {}),
      }),
    );
    Object.freeze(this);
  }
}

/**
 * Discards messages, causes, stacks, bodies, and all unrecognized exception data.
 * @param {unknown} error - Unknown failure to classify without exposing secrets.
 * @param {RequestContext} context - Request-local identity, cancellation, or diagnostic context.
 * @returns {ErrorEnvelope} Bounded secret-safe application error envelope.
 */
export function errorEnvelope(
  error: unknown,
  context: RequestContext,
): ErrorEnvelope {
  const details =
    error instanceof ApplicationFailure ? failures.get(error) : undefined;

  const code = details?.code ?? "INTERNAL_ERROR";

  return ErrorEnvelopeSchema.parse({
    error: {
      ...details,
      code,
      message: errorPolicy[code][0],
      retryable:
        errorPolicy[code][1] ||
        (code === "TOKEN_REFRESH_FAILED" &&
          details?.reason === "transient_refresh"),
      request_id: requestId(context),
    },
  });
}

/**
 * Projects an unknown failure into the safe MCP tool-error envelope while preserving
 * intentional protocol failures.
 * @param {unknown} error - Unknown failure to classify without exposing secrets.
 * @param {RequestContext} context - Request-local identity, cancellation, or diagnostic context.
 * @returns {object} MCP tool-error result containing the safe application envelope.
 * @throws {ProtocolFailure} If the supplied failure belongs to the HTTP or MCP protocol boundary.
 */
export function toolError(error: unknown, context: RequestContext) {
  if (error instanceof ProtocolFailure) {
    throw new ProtocolFailure(error.domain);
  }

  const structuredContent = errorEnvelope(error, context);

  return {
    isError: true as const,
    structuredContent,
    content: [
      { type: "text" as const, text: JSON.stringify(structuredContent) },
    ],
  };
}

/** HTTP/JSON-RPC faults are separate and cannot be serialized as application details. */
export type FailureDomain =
  | "http"
  | "mcp_protocol"
  | "tool"
  | "oauth_session"
  | "upstream"
  | "configuration"
  | "internal";

/**
 * Represents an HTTP or MCP protocol rejection that must stay outside tool error envelopes.
 *
 * Transport code catches this discriminator and emits protocol-owned status/code responses
 * without exposing arbitrary exception details to the model-facing application contract.
 */
export class ProtocolFailure extends Error {
  /**
   * Creates a protocol failure for the owning transport domain.
   * @param {"http" | "mcp_protocol"} domain - Transport or application boundary responsible for the failure.
   */
  constructor(readonly domain: "http" | "mcp_protocol") {
    super("Protocol request rejected.");
    this.name = "ProtocolFailure";
    Object.freeze(this);
  }
}

function normalizeDetails(value: unknown): readonly ErrorDetail[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const unique = new Map<string, ErrorDetail>();

  for (const candidate of value) {
    const parsed = ErrorDetailSchema.safeParse(candidate);

    if (!parsed.success) {
      continue;
    }

    const detail = Object.freeze({
      field: parsed.data.field,
      reason: parsed.data.reason,
    });

    unique.set(`${detail.field}\u0000${detail.reason}`, detail);
  }

  const details = [...unique.values()]
    .sort(compareDetails)
    .slice(0, maximumErrorDetails);

  return details.length > 0 ? Object.freeze(details) : undefined;
}

function compareDetails(left: ErrorDetail, right: ErrorDetail): number {
  return (
    compareText(left.field, right.field) ||
    compareText(left.reason, right.reason)
  );
}

function compareText(left: string, right: string): number {
  if (left < right) {
    return -1;
  }

  return left > right ? 1 : 0;
}

function isOrdered(details: readonly ErrorDetail[]): boolean {
  return details.every(
    (detail, index) =>
      index === 0 || compareDetails(details[index - 1], detail) < 0,
  );
}

function retryMetadata(retryable: boolean, seconds: unknown) {
  if (
    !retryable ||
    typeof seconds !== "number" ||
    !Number.isFinite(seconds) ||
    seconds < 0
  ) {
    return {};
  }

  return { retry_after_seconds: Math.min(3600, Math.ceil(seconds)) };
}
